    int minElement = arr[0];

    // Step 2: Iterate through the array starting from the second element
    for (size_t i = 1; i < arr.size(); i++) {
        // Step 3: Update minElement if a smaller element is found
        if (arr[i] < minElement) {
            minElement = arr[i];
        }
